__device__ __forceinline__ uint32_t pack_bf16(float lo, float hi) {
    union { __nv_bfloat16 bf[2]; uint32_t u; } u;
    u.bf[0] = __float2bfloat16(lo);
    u.bf[1] = __float2bfloat16(hi);
    return u.u;
}

// ---------------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------------
// grid: (ceil(S/BLOCK_M), B*H).  GQA: kv head = query head / (H/kvH).
// Layout: sK/sV tiles live at offsets 16 KB (K0), 24 KB (K1), 32 KB (V0),
// 40 KB (V1) of dynamic shared; sQ at offset 0. Rows are 128-bf16 = 256 B,
// swizzled in 16B chunks.
__global__ void __launch_bounds__(NUM_THREADS) attention_fwd_kernel(
    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, float scale, bool causal,
    int kv_heads, int q_per_kv)
{
    extern __shared__ __nv_bfloat16 smem[];
    const int m_tile = blockIdx.x;
    const long long bh = blockIdx.y;
    const int tid = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;

    const long long qh = bh % q_per_kv;            // query head within kv group
    const long long bhkv = bh / q_per_kv;          // kv head index
    const long long base_q = (bh * (long long)seq_len) * HEAD_DIM;
    const long long base_kv = (bhkv * (long long)seq_len) * HEAD_DIM;

    const int row0 = m_tile * BLOCK_M;
    const int rows = min(BLOCK_M, seq_len - row0);
    const int col0 = warp * 16;                    // this warp's Q rows

    // ---- load Q tile (BLOCK_M x 128) into smem (offset 0), swizzled ----
    {
        const int chunk = tid & 7;
        const int lane8 = (tid >> 3) & 3;
        const int row = tid >> 5;
        const int vec = tid & 3;
        if (row < rows) {
            const int grow = row0 + row;
            const long long off = base_q + (long long)grow * HEAD_DIM;
            const int s = swz(row, chunk) + vec * 4;
            const __nv_bfloat16* src = q + off + chunk * 8 + lane8 * 32 + vec * 4;
            *(uint4*)(smem + s) = *(const uint4*)src;
        }
    }
    __syncthreads();

    const int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    const int last_full = (causal ? row0 + rows - 1 : seq_len - 1) / BLOCK_N;
    const int ntiles = causal ? last_full + 1 : n_tiles;

    // ---- accumulator state (per thread: rows {g,g+8} x cols {2h,2h+1}) ----
    float acc_o[2][2];       // O rows {g,g+8}, cols {2h,2h+1}
    float m_prev = -INFINITY, m_cur = -INFINITY, l_prev = 0.f, l_cur = 0.f;

    uint32_t q_frag[4][4];   // [kstep][reg], 8 bf16 for this 16-row strip
    // Build Q fragments from smem (ldmatrix x4): 4 ldmatrix per 16-kstep,
    // rows: warp's 16 rows; cols 2h..2h+7 (step 0) and +8 (step 1).
    // Lane l of group g holds (row g, col 2h..2h+7) -> fragment A rows g.
    // Reorder: A wants a0..a3 = (g, 2h),(g,2h+1),(g,2h+8),(g,2h+9) across
    // regs r0..r3 -> ldmatrix outputs per lane: r0=(g,2h),(g,2h+1),
    // r1=(g,2h+2),(g,2h+3), r2=(g,2h+4),(g,2h+5), r3=(g,2h+6),(g,2h+7).
    // So for step 0: a0=r0, a1=r1, a2=r2, a3=r3.  Step 1 (cols +8): same.
    {
        const int g = lane >> 2, h = lane & 3;
        const int swz_addr = swz(col0 + g, (h * 16) / 16) + (h * 16) % 16 / 4;
        uint32_t r[4];
        // step 0: cols 2h..2h+7  -> chunk h (16 B), vec h*4
        ldmatrix_x4(r, smem + swz(col0 + g, h) + h * 4);
        q_frag[0][0] = r[0]; q_frag[0][1] = r[1]; q_frag[0][2] = r[2]; q_frag[0][3] = r[3];
        // step 1: cols 2h+8..2h+15 -> chunk h+4, vec h*4
        ldmatrix_x4(r, smem + swz(col0 + g, h + 4) + h * 4);
        q_frag[1][0] = r[0]; q_frag[1][1] = r[1]; q_frag[1][2] = r[2]; q_frag[1][3] = r[3];
    }
    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 2; ++j) acc_o[i][j] = 0.f;

    // ---- prefetch K tile 0 ----
    {
        const int chunk = tid & 7, lane8 = (tid >> 3) & 3, vec = tid & 3;
        const int grow = chunk * 4 + lane8;
        if (grow < seq_len) {
            cp_async16(smem + SMEM_Q_BYTES / 2 + swz(grow, chunk) + vec * 4,
                       k + base_kv + (long long)grow * HEAD_DIM + chunk * 8 + vec * 4);
        }
    }
    cp_async_commit();

    int nt = 0;
    for (; nt < ntiles; ++nt) {
        const bool first = (nt == 0);
        const bool last = (nt == ntiles - 1);

        // issue K for nt+1 (and V for nt) into the other buffer
        const int buf = nt & 1;
        __nv_bfloat16* sK = smem + SMEM_Q_BYTES / 2 + buf * SMEM_KV_BYTES / 2;
        __nv_bfloat16* sV = smem + SMEM_Q_BYTES / 2 + (2 + buf) * SMEM_KV_BYTES / 2;
        if (!last) {
            const int chunk = tid & 7, lane8 = (tid >> 3) & 3, vec = tid & 3;
            const int grow = chunk * 4 + lane8;
            const int gn = (nt + 1) * BLOCK_N + grow;
            if (gn < seq_len) {
                cp_async16(sK + swz(grow, chunk) + vec * 4,
                           k + base_kv + (long long)gn * HEAD_DIM + chunk * 8 + vec * 4);
            }
        }
        if (nt > 0 || !first) {
            // (V for this tile was issued last iteration; nothing to do now)
        }
        // V for this tile:
        {
            const int chunk = tid & 7, lane8 = (tid >> 3) & 3, vec = tid & 3;
            const int grow = chunk * 4 + lane8;
            const int gn = nt * BLOCK_N + grow;
            if (gn < seq_len) {
                cp_async16(sV + swz(grow, chunk) + vec * 4,
                           v + base_kv + (long long)gn * HEAD_DIM + chunk * 8 + vec * 4);
            }
        }
        cp_async_commit();

        // wait for this tile's K (issued one iteration ago, or in prefetch)
        cp_async_wait<2>();
        __syncthreads();

        // ---- QK^T: acc_s[16x32] = Q strip x K tile ----
        // K fragments via ldmatrix x4.trans on sK: lanes of group g feed
        // addresses of rows 8g..8g+7 -> trans gives (k, 2h..2h+7).
        float acc_s[2][4];  // [m half][4 regs]
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 4; ++j) acc_s[i][j] = 0.f;
        {
            const int g = lane >> 2, h = lane & 3;
            uint32_t kb[2][4];
            // 4 ksteps of 8 cols each = 32 cols; each step: ldmatrix x4.trans
            // of rows 8g..8g+7, cols 8h..8h+7 (chunk h, vec 0)
            for (int ks = 0; ks < 4; ++ks) {
                ldmatrix_x4_trans(kb[ks], sK + swz(8 * g, 4 * ks + h) + (4 * ks + h) * 4);
            }
            // Q fragment is already in q_frag[2][4]: rows g, cols 2h..2h+15
            for (int ks = 0; ks < 2; ++ks) {
                // K cols for this mma: kstep ks' -> b regs
                // acc_s row-half r uses q_frag[ks], B = kb[2*ks..2*ks+1]
                uint32_t b0[2] = {kb[2*ks][0], kb[2*ks][1]};
                uint32_t b1[2] = {kb[2*ks+1][0], kb[2*ks+1][1]};
                float c0[4] = {0,0,0,0}, c1[4] = {0,0,0,0};
                // mma 1: rows 0-15 x cols 0-7   (B k-rows 0..7 = kb[2*ks] cols 0..7)
                // but trans gave (k, col) per lane: kb[2*ks] holds (k=2h..2h+7? no)
                // -- see note: trans fragment per lane = (2h, g),(2h+1, g) etc.
                // We instead build B regs directly:
                uint32_t b_lo[2];
                b_lo[0] = kb[2*ks][0]; b_lo[1] = kb[2*ks][1];
                mma16n8k16(c0, q_frag[ks], b_lo, c0);
                mma16n8k16(c1, q_frag[ks], b1, c1);
                for (int j = 0; j < 4; ++j) { acc_s[0][j] += c0[j]; acc_s[1][j] += c1[j]; }
            }
        }
        (void)acc_s;
        (void)acc_o; (void)m_cur; (void)l_cur;
        __syncthreads();
    }

    // ---- epilogue: write O ----
    {
        const int g = lane >> 2, h = lane & 3;
        for (int i = 0; i < 2; ++i) {
            const int grow = row0 + col0 + g + i * 8;
            if (grow < seq_len) {
                const float inv = l_cur > 0.f ? 1.f / l_cur : 0.f;
                float o0 = acc_o[i][0] * inv, o1 = acc_o[i][1] * inv;
                out[base_q + (long long)grow * HEAD_DIM + 2 * h] = __float2bfloat16(o0);
                out[base_q + (long long)grow * HEAD_DIM + 2 * h + 1] = __float2bfloat16(o1);
            }
        }
    }
}

}  // namespace

