    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);

    // 16-byte vectorized K/V tile load: BLOCK_N*HEAD_DIM/8 = 1024 vecs.
    const int kV_vecs = BLOCK_N * HEAD_DIM / 8;
    const __nv_bfloat16* kk = k + base;
    const __nv_bfloat16* vv = v + base;

    for (int nt = 0; nt < n_tiles; ++nt) {
#pragma unroll
        for (int vec = 0; vec < kV_vecs / NUM_THREADS; ++vec) {
            const int idx = vec * NUM_THREADS + threadIdx.x;
            const int row = idx / (HEAD_DIM / 8);
            const int col8 = (idx % (HEAD_DIM / 8)) * 8;
            const int grow_kv = nt * BLOCK_N + row;
            if (grow_kv < seq_len) {
                const long long off = (long long)grow_kv * HEAD_DIM + col8;
                *(uint4*)(&sK[row][col8]) = *(const uint4*)(kk + off);
                *(uint4*)(&sV[row][col8]) = *(const uint4*)(vv + off);
            } else {
                *(uint4*)(&sK[row][col8]) = make_uint4(0, 0, 0, 0);
                *(uint4*)(&sV[row][col8]) = make_uint4(0, 0, 0, 0);
            }
        }
        __syncthreads();

        for (int r = 0; r < ROWS_PER_WARP; ++r) {
            const int grow = m_tile * BLOCK_M + warp * ROWS_PER_WARP + r;
            if (grow >= seq_len) continue;  // uniform across the warp
            for (int c = 0; c < BLOCK_N; ++c) {
                const int gcol = nt * BLOCK_N + c;
                if (gcol >= seq_len) break;          // uniform across the warp
                if (causal && gcol > grow) break;    // columns are ascending

                float partial = 0.f;
#pragma unroll
                for (int j = 0; j < D_PER_LANE; ++j)
                    partial += q_reg[r][j] * __bfloat162float(sK[c][d0 + j]);
                const float s = warp_sum(partial) * scale_log2;

                // Online softmax at column granularity (tile size 1), exp2.
                const float m_new = fmaxf(row_max[r], s);
                const float corr = exp2f(row_max[r] - m_new);  // exp(-inf)=0
                const float p = exp2f(s - m_new);
                row_sum[r] = row_sum[r] * corr + p;
#pragma unroll
                for (int j = 0; j < D_PER_LANE; ++j)
                    acc[r][j] = acc[r][j] * corr
                              + p * __bfloat162float(sV[c][d0 + j]);
                row_max[r] = m_new;
            }
        }
        __syncthreads();
    }

#pragma unroll
    for (int r = 0; r < ROWS_PER_WARP; ++r) {
        const int grow = m_tile * BLOCK_M + warp * ROWS_PER_WARP + r;
        if (grow >= seq_len) continue;
        const float inv = row_sum[r] > 0.f ? 1.f / row_sum[r] : 0.f;
#pragma unroll
        for (int j = 0; j < D_PER_LANE; ++j)
            out[base + (long long)grow * HEAD_DIM + d0 + j]
                = __float2bfloat16(acc[r][j] * inv);
    }
}

